// Ledger — bundled document assets.
//
// The corner artwork is extracted from the business's own Canva invoice, so the
// generated PDF carries the same decoration rather than an approximation of it.
// The typeface stands in for Garet, which Canva licenses and cannot be
// redistributed; Poppins is the nearest free geometric sans.
//
// Everything is inlined as base64 so the renderer never depends on a network
// fetch at request time.

/** base64 → bytes, without pulling in a std dependency. */
export function bytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}


